return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=1; plural=0;','language'=>'vi','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-08T20:37:32+00:00','po-revision-date'=>'2026-09-08T20:37:32+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'Một công cụ lưu đệm và tối ưu hóa hoàn chỉnh cho WordPress: bộ đệm toàn trang, bộ đệm đối tượng, dọn dẹp cơ sở dữ liệu và tối ưu hóa CSS/JS. Hãy cài đặt tính năng này khi máy chủ lưu trữ của bạn không cung cấp lớp bộ đệm riêng — trên dịch vụ lưu trữ của Zinn Digital® thay vào đó hãy cài đặt Zinn® Cache. Bộ nhớ đệm toàn trang yêu cầu máy chủ LiteSpeed hoặc OpenLiteSpeed có mô-đun LSCache. Một bản fork theo giấy phép GPLv3 của plugin LiteSpeed Cache.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d giờ','%d hour'=>'%d giờ','%d minutes'=>'%d phút','%d minute'=>'%d phút','Purged All!'=>'Đã xóa sạch tất cả!','Purged the blog!'=>'Đã xóa sạch blog!','Purged the URL!'=>'Đã xóa bộ nhớ đệm URL!','Purged!'=>'Đã dọn dẹp!','Failed to upgrade.'=>'Nâng cấp thất bại.','Upgraded successfully.'=>'Đã nâng cấp thành công.','Dashboard'=>'Trang tổng quan','OptimaX'=>'OptimaX','Presets'=>'Cấu hình có sẵn','General'=>'Chung','Cache'=>'Bộ nhớ đệm','CDN'=>'CDN','Image Optimization'=>'Tối ưu hóa hình ảnh','Page Optimization'=>'Tối ưu hóa trang','Database'=>'Cơ sở dữ liệu',